(async function () {
  const promotionId = automaRefData(
    "loopData",
    "loop-session.data.promotionid",
  );

  if (!promotionId) {
    console.log(">> No promotionId");
    automaNextBlock();
    return;
  }

  console.log("=================================");
  console.log(">> START SESSION:", promotionId);

  // ===== 1. GET ITEM IDS =====
  let itemIds = [];

  try {
    const res = await fetch(
      `https://shopee.vn/api/v4/flash_sale/get_all_itemids?promotionid=${promotionId}&need_personalize=true&sort_soldout=true`,
      { credentials: "include" },
    );

    const json = await res.json();
    itemIds = (json?.data?.item_brief_list || []).map((i) => i.itemid);

    console.log(`>> Got ${itemIds.length} itemIds`);
  } catch (err) {
    console.error(">> ERROR get_all_itemids:", err);
    automaNextBlock();
    return;
  }

  if (!itemIds.length) {
    console.log(">> No items");
    automaNextBlock();
    return;
  }

  // ===== 2. GET ITEM DETAIL =====
  const FETCH_BATCH = 16;
  const allItems = [];
  const randomDelay = (min, max) =>
    Math.floor(Math.random() * (max - min + 1)) + min;

  for (let i = 0; i < itemIds.length; i += FETCH_BATCH) {
    automaResetTimeout();
    const batch = itemIds.slice(i, i + FETCH_BATCH);

    try {
      const res = await fetch(
        "https://shopee.vn/api/v4/flash_sale/flash_sale_batch_get_items",
        {
          method: "POST",
          credentials: "include",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            promotionid: promotionId,
            itemids: batch,
            categoryid: 0,
            limit: batch.length,
            with_dp_items: true,
          }),
        },
      );

      const json = await res.json();

      // Check captcha error
      if (json.error === 90309999) {
        console.error(">> CAPTCHA ERROR detected");

        try {
          await fetch("https://n8n.piggi.me/webhook/sent-tele-error", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              message: `🚨 *CAPTCHA DETECTED*

Workflow bị chặn bởi captcha

⚠️ Vui lòng giải captcha để tiếp tục
🕐 ${new Date().toLocaleString("vi-VN")}`,
            }),
          });
          console.log(">> Captcha notification sent");
        } catch (err) {
          console.error(">> Failed to send captcha notification:", err);
        }

        // Stop processing
        automaNextBlock();
        return;
      }

      const items = json?.data?.items || [];

      allItems.push(...items);

      console.log(`>> Batch ${i / FETCH_BATCH + 1}: ${items.length}`);

      await new Promise((r) => setTimeout(r, randomDelay(500, 1500)));
    } catch (err) {
      console.error(">> ERROR batch:", err);
    }
  }

  console.log(`>> Collected ${allItems.length} items`);

  if (!allItems.length) {
    automaNextBlock();
    return;
  }

  // ===== 3. TRANSFORM =====
  const removeVietnameseTones = (str = "") =>
    str
      .normalize("NFD")
      .replace(/[̀-ͯ]/g, "")
      .replace(/đ/g, "d")
      .replace(/Đ/g, "D");

  // Helper: Escape SQL string để tránh break syntax khi inject vào n8n template
  // Escape order: backslash FIRST, then single quote
  const escapeSQLString = (str) => {
    if (!str) return "";
    return str
      .replace(/\\/g, "\\\\") // \ → \\ (MUST escape backslash first!)
      .replace(/'/g, "''"); // ' → '' (MySQL standard escape)
  };

  // --- DATA 1: DB insert ---
  const dbItems = allItems.map((item) => ({
    promotionId: item.promotionid,
    productName: escapeSQLString(item.name || ""),
    productNameNormalized: escapeSQLString(removeVietnameseTones(item.name)),
    ratingStar: item.item_rating?.rating_star,
    price: item.price_before_discount,
    priceFlashsale: item.price || null,
    hiddenPriceDisplay: item.hidden_price_display || null,
    discountPercent: item.raw_discount,
    flashSaleStock: item.flash_sale_stock,
    stock: item.stock,
    shopId: item.shopid,
    itemId: item.itemid,
    imageUrl: item.image,
    productCatId: item.flash_catid,
    startTime: item.start_time,
    endTime: item.end_time,
    metadata: escapeSQLString(JSON.stringify(item)), // Escape metadata JSON
  }));

  // --- DATA 2: product feed ---
  const productItems = allItems
    .map((e) => ({
      link: `https://shopee.vn/product/${e.shopid}/${e.itemid}`,
      image: e.image,
      product_name: e.name,
      shopId: e.shopid,
      itemId: e.itemid,
      source: "flash_sale",
      price: (e.price_before_discount || 0) / 100000,
    }))
    .filter((e) => e.price >= 50000);

  console.log(`>> DB items: ${dbItems.length}`);
  console.log(`>> Product feed: ${productItems.length}`);

  // ===== 4. SEND DB (insert-to-shopee) =====
  const SEND_BATCH = 500;

  for (let i = 0; i < dbItems.length; i += SEND_BATCH) {
    automaResetTimeout();
    const batch = dbItems.slice(i, i + SEND_BATCH);
    const batchNumber = Math.floor(i / SEND_BATCH) + 1;

    try {
      console.log(`>> Sending DB batch ${batchNumber}`);

      const res = await fetch(
        "https://n8n.piggi.me/webhook/insert-to-shopee-v2",
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(batch),
        },
      );

      if (!res.ok) {
        console.error(`>> DB batch ${batchNumber} failed: ${res.status}`);
      }
    } catch (err) {
      console.error(`>> DB batch ${batchNumber} error:`, err);
    }
  }

  // ===== 5. SEND PRODUCT FEED =====
  if (productItems.length) {
    try {
      console.log(">> Sending product feed");

      const res = await fetch(
        "https://n8n.piggi.me/webhook/lab_shopee_products_v2",
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(productItems),
        },
      );

      if (!res.ok) {
        console.error(`>> Product feed failed: ${res.status}`);
      }
    } catch (err) {
      console.error(">> Product feed error:", err);
    }
  }

  window.sessionStats = window.sessionStats || [];

  window.sessionStats.push({
    promotionId,
    totalItems: allItems.length,
    productFeed: productItems.length,
  });

  console.log(">> DONE SESSION:", promotionId);

  // automaNextBlock();

  automaNextBlock({ title: "Delay" }, { nextBlockId: "cbg13pq" });
})();

(async function () {
  console.log(">> Fetching Shopee sessions...");

  try {
    const res = await fetch(
      "https://shopee.vn/api/v4/flash_sale/get_all_sessions?tracker_info_version=1",
      {
        method: "GET",
        credentials: "include",
        headers: {
          accept: "*/*",
          "x-api-source": "pc",
          "x-requested-with": "XMLHttpRequest",
          "x-shopee-language": "vi",
        },
      },
    );

    const json = await res.json();

    // Check captcha error
    if (json.error === 90309999) {
      console.error(">> CAPTCHA ERROR detected");

      try {
        await fetch("https://n8n.piggi.me/webhook/sent-tele-error", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            message: `🚨 *CAPTCHA DETECTED*

Workflow bị chặn bởi captcha

⚠️ Vui lòng giải captcha để tiếp tục
🕐 ${new Date().toLocaleString("vi-VN")}`,
          }),
        });
        console.log(">> Captcha notification sent");
      } catch (err) {
        console.error(">> Failed to send captcha notification:", err);
      }

      automaSetVariable("SessionsArray", []);
      automaSetVariable("hasData", 0);
      automaNextBlock();
      return;
    }

    const sessions = json?.data?.sessions || [];

    const allSessions = sessions.map((s) => ({
      promotionid: s.promotionid,
      start_time: s.start_time,
      end_time: s.end_time,
    }));

    console.log(`>> Total sessions found: ${allSessions.length}`);

    // Đẩy dữ liệu vào Automa
    automaSetVariable("SessionsArray", allSessions);
    automaSetVariable("hasData", allSessions.length);
  } catch (err) {
    console.error(">> ERROR fetch sessions:", err);
    automaSetVariable("SessionsArray", []);
    automaSetVariable("hasData", 0);
  }

  window.sessionStats = [];

  automaNextBlock();
})();

let msg = "🔥 SHOPEE SUMMARY\n\n";

window.sessionStats.forEach(s => {
  msg += `🛍 ${s.promotionId}\n`;
  msg += `Items: ${s.totalItems}\n`;
  msg += `Feed: ${s.productFeed}\n\n`;
});

alert(msg);
automaNextBlock()
